coding.referenceSolution:
def to_mb(size):
    units = {"GB": 1000, "MB": 1, "kB": 0.001}
    for unit, factor in units.items():
        if size.endswith(unit):
            return round(float(size[:-len(unit)]) * factor, 6)
    if size.endswith("B"):
        return round(float(size[:-1]) / 1_000_000, 6)
    return 0

