coding.referenceSolution:
def to_delete(images, keep):
    by_repo = {}
    for image in images:
        by_repo.setdefault(image["repo"], []).append(image)
    out = []
    for repo_images in by_repo.values():
        repo_images.sort(key=lambda i: i["created"], reverse=True)
        out += [f"{i['repo']}:{i['tag']}" for i in repo_images[keep:]]
    return sorted(out)
